-- Postgres variant of 0967_admin_change_summaries.sql (issue #977). The composite foreign key stands in for the
-- cross-tenant triggers. rls.sql is regenerated by `tessera admin gen-rls`.

-- +goose Up
CREATE TABLE admin_change_summaries (
  tenant_id TEXT NOT NULL REFERENCES tenants (id),
  change_id TEXT NOT NULL,
  summary TEXT NOT NULL CHECK (length(summary) BETWEEN 1 AND 1000),
  PRIMARY KEY (tenant_id, change_id),
  FOREIGN KEY (tenant_id, change_id) REFERENCES admin_change_requests (tenant_id, id)
);
